import React, { useState } from 'react';
import { useApp } from '../context/AppContext';
import { kitchenApi } from '../utils/api';
import toast from 'react-hot-toast';

const STATUS_STYLE = {
  confirmed: 'border-blue-500 bg-blue-900/40',
  in_preparation: 'border-amber-500 bg-amber-900/40',
  ready: 'border-emerald-500 bg-emerald-900/40',
};

const STATUS_LABEL = {
  confirmed: 'QUEUED',
  in_preparation: 'PREPARING',
  ready: 'READY',
};

export default function KitchenView() {
  const { kitchenQueue, refreshKitchen, refreshTables } = useApp();
  const [loading, setLoading] = useState('');

  async function action(fn, label) {
    setLoading(label);
    try {
      await fn();
      await refreshKitchen();
      await refreshTables();
    } catch (err) {
      toast.error(err.response?.data?.error || 'Action failed');
    } finally {
      setLoading('');
    }
  }

  const { activeOrders = [], commandHistory = [] } = kitchenQueue;

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h2 className="text-2xl font-bold text-white">Kitchen Queue</h2>
        <button
          onClick={() => action(() => kitchenApi.undo().then((r) => toast.success(`Undone: ${r.message || 'last action'}`)), 'undo')}
          disabled={!!loading}
          className="btn bg-red-800 hover:bg-red-700 text-white disabled:opacity-50"
        >
          {loading === 'undo' ? 'Undoing...' : 'Undo Last Action'}
        </button>
      </div>

      {activeOrders.length === 0 ? (
        <div className="text-center text-gray-500 py-20">No active orders in the kitchen</div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
          {activeOrders.map((order) => (
            <div key={order.id} className={`rounded-xl border-2 p-4 ${STATUS_STYLE[order.status]}`}>
              <div className="flex justify-between items-start mb-3">
                <div>
                  <p className="text-white font-bold">Table {order.tableId}</p>
                  <p className="text-gray-400 text-xs">{order.id.slice(0, 8)}</p>
                </div>
                <span className="text-xs font-bold px-2 py-1 rounded-full bg-black/40 text-white">
                  {STATUS_LABEL[order.status] || order.status.toUpperCase()}
                </span>
              </div>

              <div className="space-y-1 mb-4">
                {order.items.map((item) => (
                  <div key={item.id} className="flex justify-between text-sm">
                    <span className="text-gray-200">{item.menuItem.name}</span>
                    <span className="text-gray-400">x{item.quantity}</span>
                  </div>
                ))}
              </div>

              <div className="flex gap-2">
                {order.status === 'confirmed' && (
                  <button
                    disabled={!!loading}
                    onClick={() => action(() => kitchenApi.prepare(order.id).then(() => toast.success('Started preparation')), `prep-${order.id}`)}
                    className="btn-sm bg-amber-600 hover:bg-amber-500 text-white flex-1"
                  >
                    Start Prep
                  </button>
                )}
                {order.status === 'in_preparation' && (
                  <button
                    disabled={!!loading}
                    onClick={() => action(() => kitchenApi.markReady(order.id).then(() => toast.success('Marked ready')), `ready-${order.id}`)}
                    className="btn-sm bg-emerald-600 hover:bg-emerald-500 text-white flex-1"
                  >
                    Mark Ready
                  </button>
                )}
                <button
                  disabled={!!loading}
                  onClick={() => action(() => kitchenApi.cancel(order.id).then(() => toast.success('Order cancelled')), `cancel-${order.id}`)}
                  className="btn-sm bg-red-700 hover:bg-red-600 text-white"
                >
                  Cancel
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {commandHistory.length > 0 && (
        <div className="mt-8">
          <h3 className="text-lg font-semibold text-gray-400 mb-3">Command History</h3>
          <div className="space-y-1">
            {commandHistory.slice().reverse().map((cmd, i) => (
              <div key={i} className="text-sm text-gray-500 bg-gray-800/50 rounded px-3 py-1">
                {cmd}
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
